UPDATE agent_pending_action
SET status = 'CONFIRMED',
confirmed_at = #{confirmedAt}
WHERE action_id = #{actionId}
AND user_id = #{userId}
AND status = 'PENDING'
AND expires_at > #{confirmedAt}

